import { hasDependency } from '../../util/plugin.js';
const title = 'nodemon';
const enablers = ['nodemon'];
const isEnabled = ({ dependencies }) => hasDependency(dependencies, enablers);
const config = ['nodemon.json', 'package.json'];
const packageJsonPath = 'nodemonConfig';
const resolveConfig = (config, options) => {
    if (!config.exec)
        return [];
    const inputs = options.getInputsFromScripts(config.exec, { optionalBinaries: true });
    for (const input of inputs)
        input.dir ??= options.cwd;
    return inputs;
};
const args = {
    positional: false,
    nodeImportArgs: true,
    alias: { exec: ['x'] },
    fromArgs: ['exec'],
    config: ['config'],
};
const plugin = {
    title,
    enablers,
    isEnabled,
    config,
    packageJsonPath,
    resolveConfig,
    args,
};
export default plugin;
